select strength_state, max(game_date) max_date, count(*) filter (where game_date >= '2026-11-12') rows_since_1112, count(distinct player_id) filter (where game_date='2026-11-15') p1115, count(distinct player_id) filter (where game_date='2026-11-14') p1114, count(distinct player_id) filter (where game_date='2026-11-13') p1113, max(updated_at) upd from rolling_player_game_metrics where season=20262027 and game_date >= '2026-11-10' group by 1
